def update_profile(original_name: str, updated_profile: Profile) -> Result[Profile, KrisError]:
    """Update a profile, handling renames.

    If the name changed, deletes the old file and creates a new one.

    Args:
        original_name: The original profile name (for rename detection).
        updated_profile: The updated profile to save.

    Returns:
        Success with saved profile, or Failure with error.
    """
    # If name changed, delete old first
    if original_name != updated_profile.name:
        delete_result = delete_profile(original_name)
        # Only fail if it's a real error (not "not found" which means already deleted)
        if (
            not delete_result.is_success()
            and isinstance(delete_result, Failure)
            and delete_result.error.code != ErrorCode.PROFILE_NOT_FOUND
        ):
            return Failure(delete_result.error)

    return save_profile(updated_profile)
